using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace NightLens {
internal static class SiteImageChecks {
    static int count;static void Check(bool ok,string text){if(!ok)throw new Exception(text);count++;Console.WriteLine("PASS: "+text);}static void Fails(Action action,string text){bool failed=false;try{action();}catch{failed=true;}Check(failed,text);}
    static IEnumerable<Control> Walk(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in Walk(c))yield return child;}}
    static void Shot(Form form,string file){form.Show();Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(file);}foreach(var c in Walk(form).Where(c=>c.Visible&&(c is Button||c is NumericUpDown||c is TextBox||c is ComboBox||c is CheckBox))){var bounds=form.RectangleToClient(c.RectangleToScreen(c.ClientRectangle));Check(form.ClientRectangle.Contains(bounds),form.Text+": input is inside the window");}form.Close();}
    public static int Run(){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Source",".build","site-image-checks",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        var h=HorizonProfile.Import("# north/east skyline\n350 10\n10 30 # tree\n180 0\n");Check(Math.Abs(h.Height(0)-20)<.00001&&Math.Abs(h.Height(355)-15)<.00001,"Skyline interpolation wraps correctly across north");Check(Math.Abs(h.Height(90)-(30+(0-30)*80.0/170))<.00001,"Skyline interpolation between measured points");
        Check(HorizonProfile.Import("0 5\n360 5").Points.Count==1,"Matching 0/360-degree endpoints merge");Fails(()=>HorizonProfile.Import("0 5\n360 8"),"Conflicting north endpoints are rejected");Fails(()=>HorizonProfile.Import("north twenty"),"Malformed horizon rows fail clearly");Fails(()=>HorizonProfile.Import("0 95"),"Impossible horizon elevations are rejected");Fails(()=>HorizonProfile.Import("10 20 30"),"Ambiguous three-column horizon data is rejected");
        Check(Math.Abs(HorizonProfile.Import("0 90\n180 60","azDeg_zdDeg").Height(180)-30)<.00001,"Stellarium zenith-distance mode converts to altitude");Check(Math.Abs(HorizonProfile.Import("0 0\n"+Math.PI.ToString("R",CultureInfo.InvariantCulture)+" "+(Math.PI/6).ToString("R",CultureInfo.InvariantCulture),"azRad_altRad").Height(180)-30)<.00001,"Stellarium radians are converted");Check(Math.Abs(HorizonProfile.Import("0 100\n200 66.6666666667","azGrad_zdGrad").Height(180)-30)<.00001,"Stellarium gradians and zenith distance are converted");Check(HorizonProfile.Import("0 25","azDeg_altDeg",90).Points[0].Azimuth==90,"Landscape azimuth rotation is supported");
        h.MinimumAltitude=50;Check(h.Limit(180)==50,"Minimum altitude is enforced above lower skyline points");h.Enabled=false;Check(h.Limit(0)==50,"Disabling skyline retains the configured altitude floor");
        var legacy=Json.Read<Settings>("{\"WindowsLocation\":false}");SiteLibrary.Normalize(legacy);Check(legacy.Sites.Count==0&&legacy.Horizon.MinimumAltitude==30,"Older settings gain safe site/horizon defaults");
        var settings=new Settings{WindowsLocation=false};SiteLibrary.Normalize(settings);settings.Horizon=HorizonProfile.Import("0 5\n90 8\n180 10\n270 12");settings.Horizon.AnchorLat=settings.Lat;settings.Horizon.AnchorLon=settings.Lon;
        var home=SiteLibrary.Capture(settings);home.Name="Home";settings.Sites.Add(home);settings.Horizon.Points[0].Altitude=20;Check(home.Horizon.Points[0].Altitude==5,"Saved sites copy skyline points independently");
        var travel=new ObservingSite{Name="Travel test site",Lat=36.3,Lon=-111.5,Zone="US Mountain Standard Time",Sky=new SkySite{Lat=36.3,Lon=-111.5,Bortle=2.5,RadiusKm=1,Source="Test site"},Horizon=HorizonProfile.Import("0 4\n180 15")};settings.Sites.Add(travel);SiteLibrary.Use(settings,travel);Check(!settings.WindowsLocation&&settings.ActiveSiteId==travel.Id&&settings.SavedLat==travel.Lat&&settings.Lat==travel.Lat,"Selecting a site uses saved coordinates instead of GPS");Check(SkySite.At(settings).Bortle==2.5&&settings.Rigs.Count==2,"Selecting a site restores its sky brightness and preserves equipment");SiteLibrary.Use(settings,home);Check(settings.Horizon.Points[0].Altitude==5&&settings.SavedPlace=="Home","Switching home restores that site’s skyline");
        var restored=Json.Read<Settings>(Json.Write(settings));SiteLibrary.Normalize(restored);Check(restored.Sites.Count==2&&restored.Sites[0].Horizon.Points.Count==4,"Multiple sites and skyline data survive serialization");restored.Lat=0;restored.Lon=0;Check(!SiteLibrary.HorizonAt(restored).HasMask&&SiteLibrary.HorizonMoved(restored),"GPS travel does not apply the old location's skyline");Check(SiteLibrary.Capture(restored).Horizon.Points.Count==0,"Saving a distant GPS site starts with a local empty skyline");
        Fails(()=>SiteLibrary.Validate(new ObservingSite{Name="Invalid",Lat=91,Lon=0,Zone="UTC"}),"Invalid saved coordinates are rejected");
        DateTime now=new DateTime(2026,10,24,18,0,0,DateTimeKind.Utc);var plan=new Settings{WindowsLocation=false,IncludeSolar=false,EnabledCatalogs=new List<string>{"Messier.csv"}};plan.Horizon=new HorizonProfile{MinimumAltitude=50};var high=new Night(plan,new Forecast(),now);Check(high.Picks.Count>0&&high.Picks.All(p=>p.Alt>=50),"Target planning honors a custom minimum altitude");
        plan.Horizon=HorizonProfile.Import("0 0\n90 0\n180 50\n270 80");plan.Horizon.AnchorLat=plan.Lat;plan.Horizon.AnchorLon=plan.Lon;var masked=new Night(plan,new Forecast(),now);Check(masked.PlanningStepMinutes==1&&masked.Picks.Count>0,"Skyline planning uses one-minute samples");Check(masked.Picks.All(p=>masked.Visible(p.Target,p.Best)&&(p.End-p.Start).TotalMinutes>=30),"Best targets clear the skyline in a continuous imaging window");Check(masked.Picks.All(p=>Enumerable.Range(0,(int)(p.End-p.Start).TotalMinutes+1).All(i=>masked.Visible(p.Target,p.Start.AddMinutes(i)))),"Recommended imaging windows exclude blocked minutes");
        plan.Horizon=HorizonProfile.Import("0 90");plan.Horizon.AnchorLat=plan.Lat;plan.Horizon.AnchorLon=plan.Lon;Check(new Night(plan,new Forecast(),now).Picks.Count==0,"A fully obstructed sky produces no invented targets");
        string reference=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Scripts","Fixtures","Healpix-reference.csv");foreach(string line in File.ReadLines(reference).Skip(1)){var v=line.Split(',');double ra=double.Parse(v[0],CultureInfo.InvariantCulture),dec=double.Parse(v[1],CultureInfo.InvariantCulture);int order=int.Parse(v[2]);ulong expected=ulong.Parse(v[3]);Check(SurveyImages.Nested(ra,dec,order)==expected,"HEALPix reference match: "+v[0]+", "+v[1]+" order "+order);}
        long tile;int x,y;SurveyImages.TilePixel(0,out tile,out x,out y);Check(tile==0&&x==0&&y==0,"JPEG HiPS origin follows the rotated image-grid convention");SurveyImages.TilePixel(1,out tile,out x,out y);Check(x==0&&y==1,"Nested x bits map to JPEG image rows");SurveyImages.TilePixel(2,out tile,out x,out y);Check(x==1&&y==0,"Nested y bits map to JPEG image columns");
        var target=new Target("Projection test","Nebula",83.8221/15,-5.3911,20,15);Check(SurveyImages.PixelAt(target,449,449,899,7,.5)==SurveyImages.Nested(target.Ra*15,target.Dec,16),"Survey cutout center matches the target's catalog coordinates");
        using(var img=new Bitmap(300,300)){using(var g=Graphics.FromImage(img)){g.Clear(Color.FromArgb(10,15,20));g.FillEllipse(Brushes.White,140,140,20,20);}Check(!SurveyImages.HasBlankBorder(img),"Bright object cores are not mistaken for white padding");for(int edge=0;edge<4;edge++){using(var g=Graphics.FromImage(img)){g.Clear(Color.Black);g.FillRectangle(Brushes.White,edge==0?0:edge==1?275:0,edge==2?0:edge==3?275:0,edge<2?25:300,edge<2?300:25);}Check(SurveyImages.HasBlankBorder(img),"Missing PS1 coverage rejected on side "+edge);}}
        var imageLog=new List<string>();ImageServiceTests.Run(new[]{"","","",Path.Combine(root,"preview.png"),Path.Combine(root,"images.txt")},imageLog);foreach(string line in imageLog){count++;Console.WriteLine(line);}
        foreach(string theme in new[]{"Light","Dark","Night"}){Style.SetTheme(theme);Shot(new HorizonForm(home.Horizon,home.Lat,home.Lon),Path.Combine(root,"Horizon-"+theme+".png"));Shot(new SavedSitesForm(settings),Path.Combine(root,"Sites-"+theme+".png"));Shot(new SiteEditorForm(travel),Path.Combine(root,"Site-editor-"+theme+".png"));}
        Style.SetTheme("Dark");using(var splash=new StartupSplash()){splash.Stage(3,"Fetching forecast…");Shot(splash,Path.Combine(root,"Startup.png"));}using(var splash=new StartupSplash(true)){splash.Stage(4,"Scoring targets for tonight…");Shot(splash,Path.Combine(root,"Startup-night.png"));}
        using(var main=new MainForm(true)){main.LoadTest(new Forecast(),now);using(var menu=main.BuildSettingsMenu()){Check(menu.Items.Count==5,"Settings has five focused top-level entries");Check(((ToolStripMenuItem)menu.Items[0]).DropDownItems.Count==4,"Location, sites, horizon and Bortle are grouped together");Check(((ToolStripMenuItem)menu.Items[1]).DropDownItems.Count==3,"Equipment, catalogs and current night are grouped under Planning");}Check(Walk(main).OfType<ComboBox>().Any(c=>c.AccessibleName=="Observing site"),"Dashboard exposes the quick observing-site selector");Shot(main,Path.Combine(root,"Dashboard.png"));}
        Console.WriteLine(count+" site, horizon, image and loading-screen checks passed. Previews: "+root);return count;
    }
    public static int LiveImages(){try{ObjectImages.CacheFolder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Source",".build","live-survey-images",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(ObjectImages.CacheFolder);var s=new Settings{WindowsLocation=false};string notice;var all=CatalogLibrary.Load(s,out notice);foreach(string id in new[]{"NGC1342","NGC2281","IC5070","NGC1976"}){var target=all.First(t=>t.Aliases.Contains(id));var watch=Stopwatch.StartNew();string path=ObjectImages.Get(target,true,true).Result;if(path==null)throw new Exception(id+": "+ObjectImages.ErrorFor(target));Console.WriteLine(id+" | "+ObjectImages.Survey(target)+" | "+watch.Elapsed.TotalSeconds.ToString("0.0")+"s | "+path);}return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
}
